previewCss:
.darma-loader-darma-b14-ice-cream-stack { --accent: var(--loader-color, #f472b6); --accent-2: var(--loader-secondary-color, #c084fc); width: calc(var(--loader-size, 116px) * .68); height: var(--loader-size, 116px); position: relative; display: flex; flex-direction: column; align-items: center; justify-content: flex-end; padding-bottom: 36%; }
.darma-loader-darma-b14-ice-cream-stack::after { content: ''; position: absolute; bottom: 0; left: 26%; width: 48%; height: 40%; clip-path: polygon(0 0, 100% 0, 50% 100%); background: repeating-linear-gradient(48deg, color-mix(in srgb, #000 16%, var(--accent-2)) 0 calc(var(--loader-size, 116px) * .035), var(--accent-2) calc(var(--loader-size, 116px) * .035) calc(var(--loader-size, 116px) * .07)); }
.darma-loader-darma-b14-ice-cream-stack span { border-radius: 50%; animation: darma-loader-darma-b14-ice-cream-stack-scoop calc(var(--loader-speed, 1s) * 3) cubic-bezier(.35, 1.5, .5, 1) infinite; }
.darma-loader-darma-b14-ice-cream-stack span:nth-child(1) { order: 3; width: 78%; height: calc(var(--loader-size, 116px) * .28); background: radial-gradient(circle at 36% 30%, color-mix(in srgb, #fff 34%, var(--accent)), var(--accent)); }
.darma-loader-darma-b14-ice-cream-stack span:nth-child(2) { order: 2; width: 68%; height: calc(var(--loader-size, 116px) * .245); margin-bottom: -8%; background: radial-gradient(circle at 36% 30%, color-mix(in srgb, #fff 40%, var(--accent-2)), var(--accent-2)); animation-delay: calc(var(--loader-speed, 1s) * .3); }
.darma-loader-darma-b14-ice-cream-stack span:nth-child(3) { order: 1; width: 56%; height: calc(var(--loader-size, 116px) * .2); margin-bottom: -7%; background: radial-gradient(circle at 36% 30%, #fff, color-mix(in srgb, #fff 55%, var(--accent))); animation-delay: calc(var(--loader-speed, 1s) * .6); }
@keyframes darma-loader-darma-b14-ice-cream-stack-scoop { 0% { opacity: 0; transform: translateY(-58%) scale(.7); } 12% { opacity: 1; } 22% { transform: translateY(0) scale(1.08); } 30% { transform: translateY(0) scale(1); } 82% { opacity: 1; transform: translateY(0) scale(1); } 94%, 100% { opacity: 0; transform: translateY(0) scale(0); } }

